// Turn the model's question lines into form fields for the next page.
const raw = $input.first().json.text || '';
const questions = raw
  .split('\n')
  .map((l) => l.replace(/^\s*(?:[-*\u2022]|\d+[.)])\s*/, '').trim())
  .filter((l) => l.length > 0)
  .slice(0, 6);

const formFields = questions.map((q) => ({
  fieldLabel: q,
  fieldType: 'textarea',
  requiredField: false,
}));

return [{ json: { questions, formFields } }];

// Pair every question with its answer and carry the form data forward.
const form = $('On idea submitted').first().json;
const questions = $('Build question fields').first().json.questions || [];
const answers = $input.first().json || {};

const clarifying_qa = questions
  .map((q) => `**${q}**\n${(answers[q] || '').toString().trim()}`)
  .join('\n\n');

return [
  {
    json: {
      draft: form.draft,
      platform: form.platform,
      goal: form.goal || '',
      clarifying_qa,
    },
  },
];

// Compact the best-performing saved posts into a short voice reference.
const idea = $('Assemble idea').first().json;

const references = $input
  .all()
  .map((i) => i.json.fields || i.json)
  .filter((r) => r && r.hook)
  .slice(0, 8)
  .map((r) => `- hook: ${r.hook}\n  why it works: ${(r.why_it_works || '').toString().slice(0, 300)}`)
  .join('\n');

return [{ json: { ...idea, references: references || '(none saved yet)' } }];

