// Split the proposal into three columns and read the judge's pick.
const proposal = $('Propose 3 structures').first().json.text || '';
const evaluation = $input.first().json.text || '';
const idea = $('Build proposal input').first().json;

const parts = proposal
  .split(/^\s*={2,}\s*STRUCTURE\s*={2,}\s*$/im)
  .map((s) => s.trim())
  .filter((s) => s.length > 0);
while (parts.length < 3) parts.push('');

const best = evaluation.match(/BEST:\s*([123])/i);

const title = (idea.draft || '').split('\n')[0].trim().slice(0, 80) || 'Untitled idea';

const alphabet = 'abcdefghijklmnopqrstuvwxyz0123456789';
const approval_token = Array.from({ length: 24 }, () => alphabet[Math.floor(Math.random() * alphabet.length)]).join('');

return [
  {
    json: {
      title,
      draft: idea.draft,
      platform: idea.platform,
      goal: idea.goal,
      clarifying_qa: idea.clarifying_qa,
      structure_1: parts[0],
      structure_2: parts[1],
      structure_3: parts[2],
      evaluation,
      chosen_structure: best ? Number(best[1]) : 1,
      approval_token,
    },
  },
];

